head.script:
scwin.gLdMktTp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const sbmOptions = {
        id : "sbm_dts_isurList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_isurList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 지수
    url += "&SCREN_ID=" + 'ULDSTF15003_ISU.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_idxIndCd",
        action : "/DsclStdzServiceStatus.do",
        ref : "",
        target : "dts_idxIndCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    rdo_APPL_ISU_BAS_TP_CD.setValue("1");
    scwin.rdoApplIsuBasTpCdOnSelChange();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_isurList_OnLoadError
 * @description dts_isurList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_isurList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_isurList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.dts_isurList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_isurList_OnLoadCompleted
 * @description dts_isurList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_isurList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_isurList.errorMsg) {
            await $c.win.alert("OnLoadCompleted => " + dts_isurList.errorMsg);
        } else {

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.dts_isurList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_APPL_ISU_BAS_TP_CD_onselchange
 * @description rdo_APPL_ISU_BAS_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_APPL_ISU_BAS_TP_CD_onselchange = function() {
    try {
        scwin.rdoApplIsuBasTpCdOnSelChange();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.rdo_APPL_ISU_BAS_TP_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_IND_TP_CD_onselchange
 * @description cmb_IND_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IND_TP_CD_onselchange = function() {
    try {
        dts_idxIndCd.sort("IND_TP_CD", 0);
        // dts_idxIndCd.sort(); // W-Craft 주석처리
        dts_idxIndCd.UseFilter = true;
        dts_idxIndCd.Filter();
        if (cmb_IND_TP_CD.getValue() !== '') {
            cmb_IDX_ID.setDisabled(false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.cmb_IND_TP_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_IDX_ID_onselchange
 * @description cmb_IDX_ID onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_IDX_ID_onselchange = async function() {
    try {
        await scwin.idxIndClick();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.cmb_IDX_ID_onselchange" });
    }
};

/**
 * @method
 * @name dts_idxIndCd_OnFilter
 * @description idx Ind Cd On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_idxIndCd_OnFilter = function(row) {
    try {
        //  업종에  해당하는 지수항목을 가져온다.
        const vVal = cmb_IND_TP_CD.getValue();
        if (vVal === "") {
            return true;
        } else {
            const vVal2 = dts_idxIndCd.getCellData(row, "IND_TP_CD");
            return (vVal === vVal2) ? true : false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.dts_idxIndCd_OnFilter" });
    }
};

/**
 * @method
 * @name btn_ok_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ok_onclick = async function() {
    try {
        frame.opener.txb_isur_cd.setValue("");
        frame.opener.txb_indTpCd.setValue(cmb_IND_TP_CD.getValue());
        frame.opener.txb_idxIndCd.setValue(cmb_IDX_ID.getValue());
        if (rdo_APPL_ISU_BAS_TP_CD.getValue() === "1") {
            frame.opener.txb_com_abbrv.setValue($c.cp.valueOfIndex(cmb_IDX_ID, "TEXT", cmb_IDX_ID.getSelectedIndex()));
        } else if (rdo_APPL_ISU_BAS_TP_CD.getValue() === "3") {
            if (dts_isurList.getRowCount() > 100) {
                await $c.win.alert("법인선택은 100개 까지 가능합니다.");
                return;
            }
            let vars = "";
            for (let j = 1; j <= dts_isurList.getRowCount(); j++) {
                const asNm = dts_isurList.getCellData(j, "COM_ABBRV");
                if (asNm !== "") {
                    if (j === 1) {
                        vars = asNm;
                    } else {
                        vars = vars + "," + asNm;
                    }
                }
            }
            frame.opener.txb_com_abbrv.setValue(vars);
            const prt = $c.frame.path("../");
            prt.dts_isurList.ClearData();
            prt.grd_isurList.setBroadcast(false);
            dts_isurList.setBroadcast(false);
            for (let i = dts_isurList.getRowCount(); i > 0; i--) {
                if (prt.dts_isurList.NameValueRow("ISUR_CD", dts_isurList.getCellData(i, "ISUR_CD")) === 0) {
                    prt.dts_isurList.AddRow();
                    const aRow = prt.dts_isurList.getRowCount();
                    prt.dts_isurList.setCellData(aRow, "ISUR_CD", dts_isurList.getCellData(i, "ISUR_CD"));
                }
            }
            dts_isurList.setBroadcast(true, true);
            prt.grd_isurList.setBroadcast(true);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.btn_ok_onclick" });
    }
};

/**
 * @method
 * @name btn_excelUpload_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_excelUpload_onclick = function() {
    try {
        const res = window.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.");
        if (res) {
            grd_isurList.Redraw = false;
            dts_isurList.removeAll();
            dts_isurList.Do("LoadExcelData", "'','Sheet1',1,0,2");
            dts_isurList.setBroadcast(false);
            for (let i = dts_isurList.getRowCount(); i > 0; i--) {
                if (dts_isurList.getCellData(i, "ISUR_CD") === "") {
                    dts_isurList.removeRow(i);
                }
            }
            dts_isurList.setBroadcast(true, true);
            grd_isurList.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.btn_excelUpload_onclick" });
    }
};

/**
 * @method
 * @name btn_excelDownload_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_excelDownload_onclick = function() {
    try {
        location.href = encodeURI("../dsclstdz/excelUploadForm.xls");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.btn_excelDownload_onclick" });
    }
};

/**
 * @method
 * @name btn_comDelete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_comDelete_onclick = async function() {
    try {
        await scwin.isurDelete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.btn_comDelete_onclick" });
    }
};

/**
 * @method
 * @name btn_comSearch_onclick
 * @description 「선택」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_comSearch_onclick = async function() {
    try {
        await scwin.popIsurSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.btn_comSearch_onclick" });
    }
};

/**
 * @method
 * @name grd_isurList_onheadcheckclick
 * @description grd_isurList onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_isurList_onheadcheckclick = function(col, colid, bCheck) {
    try {
        const cnt = dts_isurList.getRowCount();
        if (cnt > 0) {
            grd_isurList.Redraw = false;
            dts_isurList.setBroadcast(false);
            for (let i = 1; i <= cnt; i++) {
                dts_isurList.setCellData(i, "CHK_FLAG", bCheck);
            }
            dts_isurList.setBroadcast(true, true);
            grd_isurList.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003_ISU.grd_isurList_onheadcheckclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name idxIndClick
 * @description 선택한 지수의 법인리스트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.idxIndClick = async function() {
    // 선택한 지수의 법인리스트
    url += "&IDX_ID=" + cmb_IDX_ID.getValue();
    url += "&SCREN_ID=" + 'ULDSTF15003_ISU.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_isurList",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_isurList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name rdoApplIsuBasTpCdOnSelChange
 * @description 종목라디오 버튼 변경시
 * @returns {void}
 * @hidden N
 */
scwin.rdoApplIsuBasTpCdOnSelChange = function() {
    // 지수
    if (rdo_APPL_ISU_BAS_TP_CD.getValue() === "1") {
        cmb_IND_TP_CD.setDisabled(false); // 업종 selectBox
        cmb_IDX_ID.setDisabled(true); // 지수 selectBox
        dts_isurList.removeAll();
        btn_comSearch.setDisabled(true);
        btn_excelUpload.setDisabled(true); // 엑셀업로드
        btn_comDelete.setDisabled(true); // 종목삭제

    }
    // 발행회사
    else if (rdo_APPL_ISU_BAS_TP_CD.getValue() === "3") {
        cmb_IND_TP_CD.setValue("");
        cmb_IDX_ID.setValue("");
        cmb_IND_TP_CD.setDisabled(true); // 업종 selectBox
        cmb_IDX_ID.setDisabled(true); // 지수 selectBox

        dts_isurList.removeAll();
        btn_comSearch.setDisabled(false);
        btn_excelUpload.setDisabled(false); // 엑셀업로드
        btn_comDelete.setDisabled(false); // 종목삭제

    }
};

/**
 * @method
 * @name popIsurSearch
 * @description pop Isur Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popIsurSearch = async function() {
    // dts_isurList.ClearData();
    const options = {
        id: "ULDSTF28112",
        title: "발행회사 검색",
        type: "browserPopup",
        width: "360px",
        height: "450px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclstdz/ULDSTF28112.gfm", options);
};

/**
 * @method
 * @name isurDelete
 * @description isur Delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isurDelete = async function() {
    if (!scwin.cntDatasetRowCheck(dts_isurList)) {
        await $c.win.alert("삭제 할 종목을 선택하여 주십시요");
        return;
    }
    grd_isurList.Redraw = false;
    dts_isurList.setBroadcast(false);
    for (let i = dts_isurList.getRowCount(); i > 0; i--) {
        if (dts_isurList.getCellData(i, "CHK_FLAG") === 1) {
            dts_isurList.removeRow(i);
        }
    }
    dts_isurList.setBroadcast(true, true);
    grd_isurList.Redraw = true;
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    let cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name grd_isurList_CanColumnPosChange
 * @description grd isur List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_isurList_CanColumnPosChange = function(row, colid) {
    return true;
};
